async function cli(args, input = '') {
  let output = '',
    errors = '';
  const code = await runCli(args, {
    stdin: Readable.from([input]),
    stdout: {
      write(chunk) {
        output += chunk;
        return true;
      },
    },
    stderr: {
      write(chunk) {
        errors += chunk;
        return true;
      },
    },
  });
  return { code, output, errors };
}
describe('private map CLI and stream integration', () => {
